std::unordered_map<unsigned char, std::string> huffman_codes;
unsigned char byte;
while (infile.read((char*)&byte, sizeof(byte))) {
    for (int i = 7; i >= 0; --i) {
        bool bit = (byte >> i) & 1;
        if (bit) {
            if (!root->right) {
                root->right = std::make_shared<Node>('+', 0);
            }
            root = root->right;
        } else {
            if (!root->left) {
                root->left = std::make_shared<Node>('+', 0);
            }
            root = root->left;
        }
        if (!root->left && !root->right) {
            unsigned char character;
            infile.read((char*)&character, sizeof(character));
            huffman_codes[character] = "";
            std::shared_ptr<Node> temp = root;
            while (temp != std::make_shared<Node>('+', 0)) {
                if (temp == temp->parent->right) {
                    huffman_codes[character] = "1" + huffman_codes[character];
                } else {
                    huffman_codes[character] = "0" + huffman_codes[character];
                }
                temp = temp->parent;
            }
            root = std::make_shared<Node>('+', 0);
        }
    }
}

